Read cached values from the active sheet (falling back to Sheet1) and treat B3:B14 as the month keys. For each month, sum C17:G24 values whose B17:B24 date has the same year and month. Write nonzero sums as numbers and zero sums as None in C3:G14.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = wb.active.title if wb.active is not None else "Sheet1"
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

if sheet_name in vals.sheetnames:
    vws = vals[sheet_name]
elif "Sheet1" in vals.sheetnames:
    vws = vals["Sheet1"]
else:
    vws = vals.active

def parse_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if 20000 <= value <= 50000:
            return datetime(1899, 12, 30) + timedelta(days=float(value))
        return None
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        formats = [
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%Y/%m/%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d-%b-%Y",
            "%b %d, %Y",
        ]
        for fmt in formats:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
        try:
            return datetime.fromisoformat(s)
        except ValueError:
            return None
    return None

def to_number(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    return None

for r in range(3, 15):
    ref_date = parse_date(vws.cell(row=r, column=2).value)
    for c in range(3, 8):
        total = 0.0
        if ref_date is not None:
            for dr in range(17, 25):
                d = parse_date(vws.cell(row=dr, column=2).value)
                if d is None:
                    continue
                if d.year == ref_date.year and d.month == ref_date.month:
                    num = to_number(vws.cell(row=dr, column=c).value)
                    if num is not None:
                        total += num

        if total == 0:
            ws.cell(row=r, column=c).value = None
        else:
            ws.cell(row=r, column=c).value = int(total) if float(total).is_integer() else round(total, 2)

wb.save(OUT)

print("Answer sheet:", ws.title)
for r in range(3, 15):
    print(r, [ws.cell(row=r, column=c).value for c in range(3, 8)])
